    function testFuzz_property(address ownerAddr, address collat, address debtToken, bool direct, bool callback) public {
        vm.assume(ownerAddr != address(0));
        vm.assume(collat != address(0));
        vm.assume(debtToken != address(0));
        vm.assume(collat != debtToken);

        vm.prank(ownerAddr);
        // clone() itself reads the calldata layout via the immutable-args scheme.
        // To test owner(), we need c to be a clone deployed with the attacker's structure.
        // We can't directly change c's immutable storage, so we deploy a fresh CoolerFactory,
        // use its generateCooler to get the canonical clone, and read owner() there.
        // This property asserts that the returned owner must be the original caller.
        CoolerFactory factory = new CoolerFactory();
        ERC20 collatTok = ERC20(collat);
        ERC20 debtTok = ERC20(debtToken);
        vm.prank(ownerAddr);
        address cooler = factory.generateCooler(collatTok, debtTok);
        C cloneInstance = C(cooler);
        address retrievedOwner = cloneInstance.owner();
        assertTrue(retrievedOwner == ownerAddr, "owner mismatch");
    }
}

contract CoolerFactory {
    address public immutable coolerImplementation;
    mapping(address => bool) public created;
    mapping(address => mapping(address => mapping(address => address))) private coolerFor;
    mapping(address => mapping(address => address[])) public coolersFor;

    constructor() {
        coolerImplementation = address(new C());
    }

    function generateCooler(ERC20 collateral_, ERC20 debt_) external returns (address cooler) {
        cooler = coolerFor[msg.sender][address(collateral_)][address(debt_)];
        if (cooler == address(0)) {
            bytes memory coolerData = abi.encodePacked(
                msg.sender,
                address(collateral_),
                address(debt_),
                address(this)
            );
            cooler = address(coolerImplementation).clone(coolerData);
            coolerFor[msg.sender][address(collateral_)][address(debt_)] = cooler;
            coolersFor[address(collateral_)][address(debt_)].push(cooler);
            created[cooler] = true;
        }
    }

    function newEvent(uint256, uint256, uint256) external {}
}

