pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        // Deploy a minimal factory that uses the real ClonesWithImmutableArgs library
        // to clone C with controlled immutable args.
        address factory = address(new CloneDeployer());
        c = C(factory);
    }

    function testFuzz_property(address ownerAddr, uint96 upperBytes) public {
        // ownerAddr is the intended 20-byte owner
        // upperBytes fills the top 12 bytes of the 32-byte slot to trigger the shift bug
        bytes32 rawArg = bytes32(uint256(uint160(ownerAddr)) | (uint256(upperBytes) << 160));
        address expectedOwner = address(uint160(uint256(rawArg) >> 0x60));
        // Ensure the upper bytes are non-zero so the bug actually manifests
        vm.assume(upperBytes != 0);
        // Deploy clone with the raw 32-byte arg via the deployer
        address clone = CloneDeployer(address(c)).deployClone(rawArg);
        // The clone is a C instance
        C cooler = C(clone);
        // Assert: owner() must return the 20-byte address extracted via shr(0x60, ...)
        address actualOwner = cooler.owner();
        assertTrue(actualOwner == expectedOwner);
    }
}

// Minimal adversarial deployer: uses the real ClonesWithImmutableArgs library
// to encode owner in the first 32 bytes of immutable data.
contract CloneDeployer {
    using ClonesWithImmutableArgs for address;

    address public immutable implementation;

    constructor() {
        implementation = address(new C());
    }

    function deployClone(bytes32 rawArg) external returns (address clone) {
        bytes memory data = abi.encodePacked(rawArg);
        clone = implementation.clone(data);
    }
}

